source("tools/benchmark-report-assets.R")
artifact_root <- file.path("e2e", ".artifacts", "report-assets")
# This exact fixture tree is entirely regenerated by this script on every run.
if (dir.exists(artifact_root)) unlink(artifact_root, recursive = TRUE)
benchmark_report_assets(artifact_root,
                        width = 88L, height = 24L, map_count = 4L)
# Stage the current interactive specimens too, including their dynamic data.
for (kind in c("volume", "surface")) {
  write_report_bundle(file.path("e2e", ".artifacts", paste0("interactive-", kind, "-bundle.html")),
    file.path("e2e", ".artifacts", "report-assets", paste0("relocated-", kind)))
}
